from expand_a_common import *
d='p2-t1-d07'
item(d,3,'Một nhóm có 200 triệu tiền mặt, mỗi tháng chi 30 triệu và thu 10 triệu. Runway theo burn hiện tại là bao lâu?', ['10 tháng','Khoảng 6,7 tháng vì lấy tiền mặt chia toàn bộ chi phí','20 tháng vì lấy tiền mặt chia doanh thu'],'a','Net burn là 30−10=20 triệu/tháng; runway=200/20=10 tháng.',level='apply')
item(d,6,'Một dự toán đã có cloud, model API, lương và sales/marketing. Nhóm chi phí nào vẫn cần rà riêng cho AI?', ['Labeling, retraining, human review và compliance/security','Chỉ tăng doanh thu giả định để bù mọi chi phí còn thiếu','Chỉ cộng lại model API vì mọi chi phí AI đều nằm trên hóa đơn API'],'a','Hidden costs thường nằm ở việc duy trì dữ liệu, chất lượng, con người và kiểm soát hệ thống.')
item(d,7,'Những hoạt động nào thuộc hidden costs cần dự trù? (Chọn tất cả đáp án đúng.)',['Con người kiểm output trước khi giao khách','Labeling dữ liệu và cập nhật model khi cần','Kiểm định dữ liệu/an toàn','Chỉ tiền tokens của lần gọi chính'],['a','b','c'],'Hóa đơn inference không phản ánh đầy đủ chi phí vận hành sản phẩm có chất lượng.')
item(d,9,'Sản phẩm thu 50 đơn vị nhưng khi scale phát sinh tổng cost 60 đơn vị/user. Tăng số user khi economics không đổi sẽ ra sao?', ['Làm tổng lỗ tăng theo quy mô','Tự biến contribution margin thành dương','Chỉ làm giảm phần trăm lỗ vì revenue lớn hơn'],'a','Mỗi đơn vị đang lỗ 10; tăng volume không tự sửa cost/revenue trên một đơn vị.',level='apply')
item(d,10,'Dự toán đủ chi phí QA và labeling ngay từ đầu có lợi ích nào khi scale?', ['Giá và margin được đánh giá trên chi phí thực thay vì một lợi nhuận giả','Bảo đảm chi phí mỗi user không bao giờ thay đổi','Cho phép bỏ kiểm tra cost khi tăng lưu lượng'],'a','Tính đủ cost giúp nhận diện tradeoff về giá và khả năng sống còn trước khi mở rộng.')
item(d,11,'Thu hoa hồng theo giao dịch thuộc revenue model nào?', ['Transactional','Consumption tính theo mức dùng tài nguyên','SaaS/MRR với phí cố định hàng tháng'],'a','Transactional gắn doanh thu với giao dịch, khác đơn vị usage hay subscription cố định.')
item(d,11,'Một API thu tiền theo lượng tài nguyên khách dùng thuộc revenue model nào?', ['Consumption','Transactional theo tỷ lệ giao dịch thương mại','Subscription cố định không phụ thuộc lượng dùng'],'a','Consumption tính dùng bao nhiêu trả bấy nhiêu.')
item(d,15,'Tháng này sales/marketing chi 10 triệu để có 100 khách mới. CAC là bao nhiêu?', ['100 nghìn/khách','10 nghìn/khách','1 triệu/khách'],'a','CAC=tổng chi phí acquisition/số khách mới=10 triệu/100.',level='apply')
item(d,16,'ARPU 50 nghìn/tháng, COGS 20 nghìn/tháng, khách ở lại trung bình 10 tháng. LTV theo lợi nhuận gộp là bao nhiêu?', ['300 nghìn','500 nghìn do dùng nguyên doanh thu','200 nghìn do lấy COGS nhân vòng đời'],'a','Lợi nhuận gộp tháng là 30 nghìn; nhân 10 tháng được 300 nghìn.',level='apply')
item(d,17,'Trong mô hình đơn giản dùng lifetime xấp xỉ 1/churn tháng, churn 5% tương ứng lifetime nào?', ['Khoảng 20 tháng','Khoảng 5 tháng','Khoảng 0,05 tháng'],'a','Dùng tỷ lệ dạng thập phân: 1/0,05=20; đây là xấp xỉ mô hình, không phải bảo đảm từng khách.',level='apply')
item(d,18,'Doanh thu 100, COGS 40 thì gross margin bằng bao nhiêu?', ['60%','40% vì dùng COGS/revenue','150% vì chia lợi nhuận gộp cho COGS'],'a','Gross margin=(100−40)/100=60%, khác markup trên cost.',level='apply')
item(d,19,'Vì sao LTV/CAC chỉ vừa trên 1 chưa chắc tạo mô hình kinh doanh khỏe?', ['Còn cần phần đóng góp để trang trải lương, R&D và chi phí khác ngoài acquisition','Vì CAC luôn bao gồm toàn bộ chi phí sản phẩm trong mọi kỳ','Vì chỉ cần thu lại tiền marketing là đã có lợi nhuận ròng'],'a','Bù CAC chưa đồng nghĩa đủ nguồn lực vận hành và phát triển doanh nghiệp.')
item(d,20,'CAC là 100 nghìn, lợi nhuận gộp mỗi khách mỗi tháng là 10 nghìn. CAC payback là bao lâu?', ['10 tháng','1 tháng vì doanh thu tháng đã phát sinh','100 tháng vì không chia cho contribution tháng'],'a','Thời gian hoàn CAC=100/10=10 tháng nếu dòng đóng góp này giữ ổn định.',level='apply')
item(d,24,'NPV xử lý điểm nào mà cộng thẳng mọi dòng tiền tương lai sẽ bỏ qua?', ['Giá trị hiện tại của dòng tiền sau chiết khấu và vốn đầu tư ban đầu','Chỉ tổng số khách đăng ký vào cuối dự án','Chỉ số tháng khách ở lại mà không xét dòng tiền'],'a','NPV đưa dòng tiền tương lai về hiện tại trước khi so với khoản đầu tư.')
item(d,25,'Để đánh giá IRR có hấp dẫn trong mô hình dự án, cần so nó với gì?', ['Chi phí vốn yêu cầu của dự án','Chỉ doanh thu tháng đầu tiên','Chỉ tỷ lệ churn của một cohort'],'a','IRR cần được đặt cạnh cost of capital; một con số phần trăm đơn lẻ chưa đủ kết luận.')
item(d,26,'Project payback khác CAC payback ở phạm vi vốn nào?', ['Toàn bộ vốn đầu tư dự án thay vì chỉ chi phí có một khách','Chỉ chi phí quảng cáo một khách thay vì toàn bộ dự án','Cả hai luôn cùng mẫu số và cùng phạm vi chi phí'],'a','Project payback xét build/setup/R&D; CAC payback xét thu hồi acquisition cost.')
item(d,28,'Sensitivity analysis hữu ích để trả lời câu hỏi nào?', ['Adoption, ARPU hoặc churn xấu đi thì cash flow nhạy tới mức nào?','Phương án optimistic có thể được trình bày hấp dẫn đến đâu?','Có thể loại bỏ pessimistic case nếu base case đang dương không?'],'a','Thay đổi các giả định nhạy giúp phát hiện mức chịu đựng và hành động cần chuẩn bị.')
d='p2-t1-d08'
item(d,4,'Vì sao thêm một user dùng AI nhiều có thể làm tăng cost đáng kể?', ['Usage tạo thêm inference và có thể thêm công sửa output','Model đã được huấn luyện nên mọi inference đều miễn phí','Chỉ chi phí build ban đầu mới tồn tại khi có user mới'],'a','Cost biến đổi phụ thuộc công việc thực hiện, không chỉ khoản đầu tư ban đầu.')
item(d,7,'Pricing theo seat có tradeoff nào đối với AI dùng nhiều?', ['Dễ hiểu nhưng phí cố định có thể không theo kịp cost usage','Tự động gắn giá với mọi outcome được đo','Không cần cân nhắc hành vi dùng nặng của khách'],'a','Một đơn vị dễ bán chưa chắc phản ánh chi phí hoặc giá trị tạo ra ở mọi mức sử dụng.')
item(d,7,'Nhược điểm cần xử lý khi dùng usage pricing là gì?', ['Khách có thể lo hóa đơn biến động/vượt trần','Không thể đo usage dưới bất kỳ hình thức nào','Luôn cần chứng minh attribution outcome tuyệt đối trước khi thu phí'],'a','Usage giúp bảo vệ cost nhưng cần tính dễ dự đoán từ phía khách.')
item(d,8,'AI tự thực hiện công việc nhưng attribution kết quả còn yếu. Value metric nào thường an toàn hơn outcome pricing?', ['Usage','Outcome dù chưa đo được phần đóng góp của AI','Seat unlimited bất kể cost và lượng dùng'],'a','Autonomy cao chưa đủ; đo attribution yếu khiến thu theo kết quả khó kiểm chứng.')
item(d,8,'Những điều kiện nào hỗ trợ lựa chọn outcome pricing? (Chọn tất cả đáp án đúng.)',['AI có autonomy cao','Đo được attribution của kết quả','Chỉ có một demo ấn tượng nhưng chưa xác định thành công','Không xác định được khi nào khách nhận kết quả'],['a','b'],'Phải vừa thực hiện được phần việc vừa quy được kết quả vào phần việc đó.')
item(d,10,'Khi định vị giá, so với chi phí nhân công/outsource giúp ích gì hơn chỉ so phí một chatbot phổ thông?', ['Gắn giá với công việc và khoản tiết kiệm khách thực sự nhận','Bỏ qua cost cung cấp vì giá trị luôn đủ cao','Bảo đảm mọi khách có cùng willingness-to-pay'],'a','Neo giá theo giải pháp thay thế và kết quả giúp khách đánh giá giá trị của job cụ thể.')
item(d,11,'Xem pricing là giả thuyết dẫn đến cách làm nào?', ['Chọn một phương án, thử, đo và điều chỉnh','Tìm giá hoàn hảo trước khi tiếp xúc khách','Giữ giá cố định dù evidence về usage và nhu cầu đổi'],'a','Pricing cần học từ chi phí, phản ứng khách và khả năng đo kết quả.')
item(d,14,'Trước khi chọn đơn vị tính tiền, cần hiểu ngân sách của khách vì sao?', ['Sản phẩm có thể thay chi phần mềm hoặc chi nhân sự với cách đánh giá khác nhau','Khách có ngân sách thì mọi đơn vị seat/usage/outcome đều tương đương','Biết ngân sách sẽ loại bỏ nhu cầu tính Cost/Job'],'a','Nguồn ngân sách và job được thay thế ảnh hưởng cách neo và giải thích giá.')
item(d,16,'Tích hợp AI vào nơi khách đang làm việc chủ yếu giảm ma sát nào?', ['Phải mở công cụ khác và học workflow mới để nhận value','Nhu cầu kiểm chứng chất lượng output trong mọi tình huống','Mọi chi phí inference do công việc tạo ra'],'a','Phân phối qua thói quen sẵn có giảm bước chuyển ngữ cảnh, không thay thế kiểm soát chất lượng/cost.')
item(d,17,'Một trợ lý viết code xuất hiện ngay trong editor thể hiện lựa chọn phân phối nào?', ['Nhúng vào workflow hiện tại','Buộc user chuyển sang website riêng cho mỗi gợi ý','Chỉ bán qua phòng procurement mà không xét lúc dùng'],'a','Giá trị xuất hiện tại điểm người dùng đang làm nhiệm vụ, giảm hành động chuyển đổi.')
item(d,18,'Một sản phẩm phức tạp, giá cao và cần hiểu sâu khách phù hợp tradeoff nào của sales-led?', ['Deal lớn nhưng chậm và tốn nhân lực','Tự phục vụ quy mô lớn mà không cần tư vấn','Không phụ thuộc nỗ lực triển khai từng khách'],'a','Sales-led có thể phục vụ nhu cầu phức tạp nhưng economics phải nuôi được quá trình bán.')
item(d,18,'Partner-led có ưu điểm và đánh đổi nào?', ['Dùng đòn bẩy nền tảng sẵn có nhưng phụ thuộc partner và chia margin','Tự sở hữu toàn bộ kênh khách mà không cần chia lợi ích','Loại bỏ mọi chi phí inference phát sinh từ traffic'],'a','Partner mang phân phối nhưng tạo phụ thuộc và cần tính lợi nhuận sau chia sẻ.')
item(d,19,'Sản phẩm quá khó để khách tự mua nhưng giá chưa nuôi được sales team đang gặp vấn đề gì?', ['Không khớp ARPU với chi phí kênh bán','Chỉ thiếu thêm model để tăng số lựa chọn','Chỉ cần tăng số cuộc sales mà giữ nguyên economics'],'a','Kênh bán phải phù hợp mức giá và effort; có thể đổi giá/service hoặc tận dụng partner.')
item(d,20,'Pain moment nên dẫn việc chọn kênh như thế nào?', ['Có mặt ở nơi và lúc khách đang bị cản trở công việc','Chọn kênh dễ mua quảng cáo nhất rồi tìm pain phù hợp sau','Yêu cầu khách rời điểm làm việc để tìm một demo riêng'],'a','Kênh hữu ích nối điểm đau với hành động nhận giá trị ngay trong ngữ cảnh.')
item(d,23,'Một kế hoạch bắt đầu bằng vài khách trong ngành hẹp rồi mới mở rộng có mục đích gì?', ['Hiểu sâu, tạo dữ liệu/testimonial và chứng minh playbook trước scale','Tối đa số ngành cùng lúc dù chưa có quy trình lặp lại','Thay mọi evidence bằng số lượng lead rộng hơn'],'a','Beachhead hẹp tạo cơ hội học và hoàn thiện cơ chế bán/triển khai có thể nhân rộng.')
item(d,24,'Một demo được khen nhưng procurement chặn vì chưa rõ dữ liệu được dùng thế nào. Cần bổ sung gì?', ['Bằng chứng bằng văn bản về chất lượng, rủi ro và xử lý dữ liệu','Chỉ một demo trơn tru hơn mà không trả lời câu hỏi dữ liệu','Chỉ giảm giá mà giữ nguyên các thông tin chưa rõ'],'a','Bên mua cần cơ sở kiểm chứng và trách nhiệm để duyệt, không chỉ cảm giác về tính năng.')
item(d,25,'Những tài sản nào hợp thành evidence pack bán sản phẩm AI? (Chọn tất cả đáp án đúng.)',['Eval results','Risk checklist','Pilot report có kết quả thực tế','Chỉ roadmap hứa hẹn năng lực chưa được thử'],['a','b','c'],'Ba loại bằng chứng nối năng lực, kiểm soát rủi ro và tác động trong sử dụng thật.')
d='p2-t1-d09'
item(d,7,'Một leading indicator có ích phải liên hệ được với điều gì?', ['Một kết quả cụ thể mà nó báo trước','Chỉ một con số đẹp được cập nhật nhanh','Chỉ chỉ tiêu dễ lấy từ dashboard hiện có'],'a','Nhanh chưa đủ; chỉ báo sớm phải giúp dự kiến một outcome cần quản lý.')
item(d,8,'Dashboard chỉ có doanh thu, LTV/CAC và runway hạn chế khả năng điều hành thế nào?', ['Thiếu tín hiệu sớm và biến vận hành để can thiệp trước khi kết quả xấu','Đã đủ mọi bằng chứng nguyên nhân nên không cần metric khác','Càng nhiều lagging metrics càng thay thế được hành động tuần'],'a','Kết quả cuối cho biết đã xảy ra gì; điều hành cần thêm tín hiệu và đòn bẩy thay đổi.')
item(d,9,'Vì sao định nghĩa “active user” phải nói rõ điều được tính và không tính?', ['Các cách đếm mở app, hoàn thành việc hoặc quay lại có ý nghĩa khác nhau','Mọi định nghĩa active luôn cho cùng số người','Chỉ cần ghi tên metric bằng tiếng Anh là đã loại được mơ hồ'],'a','Định nghĩa tác động trực tiếp mẫu số/tử số và quyết định sản phẩm.')
item(d,10,'Tỷ lệ partner có người dùng thật không nên tính tài khoản thử do partner tự tạo vì sao?', ['Chúng chưa chứng minh phân phối tới người dùng cuối','Mọi thử nghiệm kỹ thuật đều phải được tính thành doanh thu','Bỏ chúng sẽ khiến không thể đo số partner đã ký'],'a','Metric activation của partner cần phân biệt kiểm thử nội bộ với sử dụng thực từ khách cuối.')
item(d,11,'Một mốc cảnh báo nên có cơ sở nào thay vì chọn tùy ý? (Chọn tất cả đáp án đúng.)',['Tự tính từ economics của mô hình','Baseline và mục tiêu tự đo','Benchmark phù hợp có nguồn và bối cảnh','Một tỷ lệ nghe có vẻ hợp lý nhưng không có rationale'],['a','b','c'],'Threshold cần căn cứ để biết vì sao cần can thiệp, thay vì biến mong muốn thành chuẩn.')
item(d,13,'Khách đang rời đi vì chưa nhận core value. Tăng quảng cáo ngay có rủi ro gì?', ['Đưa thêm người vào một trải nghiệm chưa giữ được họ và tăng burn','Tự giải quyết nguyên nhân khiến cohort cũ rời đi','Làm retention tốt lên chỉ nhờ mẫu acquisition lớn'],'a','Acquisition không sửa được nguyên nhân mất giá trị của người đang có.')
item(d,15,'Đối với B2B, tín hiệu nào trực tiếp phản ánh khoảng cách từ ký hợp đồng đến giá trị?', ['Thời gian đến kết quả đo được của khách','Chỉ số logo mới đã ký','Chỉ tổng số tài khoản đã cấp'],'a','Hợp đồng cần chuyển thành giá trị thực, không chỉ trạng thái đã bán.')
item(d,16,'Một nhóm free users dùng AI rất nhiều cần được theo dõi vì sao?', ['Họ có thể tạo chi phí lặp lại chưa được doanh thu bù','Số người dùng luôn là tài sản dù contribution âm','Free usage không có cost vì chưa xuất hóa đơn cho khách'],'a','Usage có cost nên cần hiểu ai tạo cost và cơ chế chuyển đổi/giới hạn phù hợp.')
item(d,18,'Average cost/user thấp nhưng heavy users gần hết revenue/user nên ưu tiên kiểm tra gì?', ['Cost distribution của nhóm dùng nặng và thiết kế gói/giới hạn phù hợp','Chỉ average vì nó đã đại diện mọi nhóm','Tăng giá tất cả ngay mà không phân tích segment'],'a','Trung bình che tail usage; can thiệp theo nhóm giúp xử lý nơi tạo mất margin.')
item(d,20,'Retention của hai cohort liên tiếp tiếp tục giảm sau ngày 30. Hướng can thiệp nào hợp lý hơn tăng paid acquisition?', ['Tập trung sửa trải nghiệm người mới và nguyên nhân họ rời đi','Chạy quảng cáo mạnh hơn để tổng user che mất cohort xấu','Chỉ đổi cách báo cáo từ cohort sang tổng số đăng ký'],'a','Tín hiệu lặp lại cho thấy cần sửa cơ chế giữ giá trị, không chỉ bù người rời bằng người mới.')
item(d,21,'Sales cycle dài cần được đối chiếu với runway để làm gì?', ['Biết khoảng thời gian thực còn lại trước khi có thể thu được tiền từ bán hàng','Coi mọi cơ hội trong pipeline như tiền mặt đã có','Bỏ chi phí triển khai vì hợp đồng đã được ký'],'a','Một runway danh nghĩa có thể rất ngắn khi phải chờ gần hết thời gian đó mới chốt doanh thu.')
item(d,22,'Tỷ lệ hợp đồng chết ở security/procurement review giúp nhận diện bottleneck nào?', ['Thiếu điều kiện/bằng chứng để bên mua duyệt','Chỉ nhu cầu luôn thấp nên không cần xem review','Chỉ thiếu chiết khấu bất kể lý do bên mua nêu'],'a','Cần phân loại nơi deal mất để chọn hành động phù hợp thay vì mặc định mọi thất bại là giá.')
item(d,23,'Muốn rút ngắn time-to-result của pilot B2B, hướng thiết kế nào phù hợp?', ['Thu về một việc, một phòng ban và một chỉ số đo được','Mở ngay toàn công ty để có nhiều use cases nhất','Tăng số tính năng hứa hẹn trước khi tích hợp xong việc đầu'],'a','Scope nhỏ tạo kết quả sớm và rõ, giảm rủi ro pilot kéo dài vì quá nhiều phụ thuộc.')
item(d,25,'Khi bán qua partner, gross margin cần được tính tại điểm nào?', ['Sau phần chia cho partner và chi phí cung cấp liên quan','Chỉ trước phần chia để giữ khả năng so sánh doanh thu','Chỉ từ số khách partner công bố có sẵn'],'a','Margin trước chia chưa phản ánh phần kinh tế thực sự giữ lại từ kênh.')
item(d,26,'Một mạng lưới có nhiều partner ký hợp đồng nhưng ít triển khai cần được đo thêm phễu nào?', ['Từ partner thực sự triển khai đến khách cuối thực sự dùng','Chỉ phễu ký thêm partner mới','Chỉ tổng số khách tiềm năng của mọi partner'],'a','Tiềm năng phân phối không bằng reach thực; cần đo cả chuyển đổi ở phía partner và khách cuối.')
item(d,28,'Những điều khoản nào có thể hạn chế rủi ro partner tăng traffic nhưng bên cung cấp gánh inference cost? (Chọn tất cả đáp án đúng.)',['Usage cap hoặc giá bậc thang','Phần vượt ngưỡng do partner chi trả','Cam kết lượng tối thiểu và chất lượng hai chiều','Phí cố định không giới hạn bất kể lượng tăng'],['a','b','c'],'Hợp đồng cần nối quyền điều khiển volume với phân bổ cost và trách nhiệm.')
item(d,30,'Kênh partner có lợi nhuận gộp sau chia quá thấp. Vì sao đẩy thêm volume chưa phải cách sửa?', ['Mỗi đơn vị có economics xấu có thể làm tổng thiệt hại lớn hơn','Volume luôn làm tỷ lệ chia partner tự giảm','Tổng doanh thu tăng bảo đảm cash flow dương'],'a','Cần điều chỉnh điều khoản hoặc kênh; tăng số đơn vị không tự sửa phần đóng góp của từng đơn vị.')
